        bg: 'radial-gradient(circle at 50% 40%, #1A080E 0%, #080406 70%)', ambient: 'neon_haze', floorPattern: 'rough',
        decor: ['neon_sign', 'brazier', 'pillar', 'pipe', 'cargo_crate'],
