const BADOR_SURFACE_ZONES = ['bador_main_base', 'bador_hq_interior', 'bador_manufacturing', 'city_outskirts_bador', 'engine_wastes', 'outpost_7', 'deep_caverns', 'zora_iv_wreckage'];

