      {[[10, 10], [150, 10], [10, 118], [150, 118]].map(([x, y], i) => <circle key={i} cx={x} cy={y} r="2.2" fill={accent} style={{ animation:`ship-blink 2.4s ease-in-out ${i * 0.4}s infinite` }} />)}
      <PropShadow cx={84} cy={71} rx={66} ry={32} />
      {/* slender swept wing blades */}
