  promenade:  { name: 'Lower Promenade',     recipe: 'market',     floor: ['#262028', '#2E2630'], wall: ['#8C6A5A', '#3A2A2A'], cover: '#D49A60', river: '#100A10', hazard: 'fire',   accent: '#FFB070', sky: ['#1C1020', '#4A2840'], decor: ['lamp', 'crate', 'plant'] },
