      {/* Left leg */}
      <rect x="3" y="21" width="6" height="7" fill="#1A1A2A"/>
      {/* Right leg */}
      <rect x="11" y="21" width="6" height="7" fill="#1A1A2A"/>
      {/* Left boot */}
      <rect x="3" y="28" width="6" height="4" fill="#0A0808"/>
